INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"地图或平面图通常按上（　）、下（　）、左（　）、右（　）绘制。","options":null}', '北；南；西；东', '地图惯例：上北、下南、左西、右东。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"早晨，当你面对太阳时，你的左边是（　）面，右边是（　）面，背对着的是（　）方。","options":null}', '北；南；西', '早晨太阳在东面，面向东：左=北，右=南，背后=西。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"面对北极星时，我们的前面是（　）面，后面是（　）面，左边是（　）面，右边是（　）面。","options":null}', '北；南；西；东', '北极星在北方，面向北：前=北，后=南，左=西，右=东。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"傍晚太阳落山时，面对夕阳，你的右面是（　）面，左面是（　）面。","options":null}', '北；南', '傍晚太阳在西面，面向西：右=北，左=南。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"刮东风时，烟囱里冒出的烟飘向（　）面；刮南风时，小树向（　）面弯腰。","options":null}', '西；北', '风向按“风吹来的方向”命名：东风从东吹来，烟向西飘；南风从南吹来，树向北弯腰。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"丽丽家在学校的东面，丽丽去上学要向（　）面走。","options":null}', '西', '学校在丽丽家的西面（东的对面是西），上学向西走。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"体育课上，小明面朝东而站，老师让他向左转，他转后应该面朝（　）而站。","options":null}', '北', '面向东时，左手指北。向左转后面朝北。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 1, '{"stem":"小海和乐乐面对面站立，小海面向北面，则乐乐面向（　）面。","options":null}', '南', '面对面站立时两人方向相反：北的对面是南。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"看图填一填：（1）商业街在古塔的（　）面，商业街在果园的（　）面。","options":null}', '西；北', '图上商业街在古塔左侧一行、果园正上方：商业街在古塔西面（左），在果园北面（上）。图布局（左→右、上→下）：商业街｜古塔｜观景台；果园｜清水河｜政务中心；儿童城｜银行｜动物园。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"看图填一填：（2）银行在清水河的（　）面，古塔在银行的（　）面。","options":null}', '南；北', '银行在清水河正下方一行、古塔在银行正上方两行：银行在清水河南面，古塔在银行北面。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"看图填一填：（3）政务中心在果园的（　）面，果园在政务中心的（　）面。","options":null}', '东；西', '政务中心与果园同一行且在右侧：政务中心在果园东面，果园在政务中心西面（相对方向互换）。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"看图填一填：（4）儿童城的北面有（　）和（　），动物园的西面有（　）和（　）。","options":null}', '果园、商业街；银行、清水河', '由近及远：儿童城正北一列依次是果园、商业街；动物园所在行往西依次是银行，银行北面（动物园西北）是清水河。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p029.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"如图是小红家的平面图。小红家卧室1在卧室2的（　）面，厨房在卧室2的（　）面；阳台的东面是（　），客厅的南面是（　）。","options":null}', '西；南；厨房；阳台', '图布局（上→下、左→右）：卫生间｜卧室1｜卧室2；客厅；阳台｜厨房（阳台在客厅正下方、厨房在阳台东侧）。卧室1在卧室2西面（左），厨房在卧室2南面（下），阳台东面是厨房，客厅南面是阳台。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p030.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"如图是某小学的平面图。（1）从校门向（　）走到水池，再向（　）走到食堂。","options":null}', '东；南', '校门在水池西侧同一行：先向东走到水池；食堂在水池下方：再向南走到食堂。图布局：花圃｜校门｜水池；办公楼｜教学楼｜食堂；风雨操场。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p030.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 3, '{"stem":"如图是某小学的平面图。（2）从风雨操场先向（　）、再向（　）走到办公楼（不经过教学楼），最后向（　）走到花圃。","options":null}', '西；北；北', '风雨操场在办公楼东南方、教学楼正下方。为不经过教学楼先向西走到办公楼正下方，再向北到办公楼；最后从办公楼向北到花圃。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p030.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '填空', 2, '{"stem":"如图是某小学的平面图。（3）从食堂向西走到（　），再向（　）走到校门。","options":null}', '教学楼；北', '食堂与教学楼同一行且食堂在东侧：向西走到教学楼；教学楼在校门下方：再向北走到校门。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p030.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 1, '{"stem":"指南针是我国古代四大发明之一，不论把它放到地球上的什么地方，它总是一端指南，另一端指（　）。","options":["A.东", "B.北", "C.西"]}', 'B', '指南针一端指南，另一端指向相反方向——北。选 B。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p030.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 1, '{"stem":"图书馆在学校的西面，学校在图书馆的（　）面。","options":["A.南", "B.北", "C.东"]}', 'C', '两个位置互换后方向相反：西的对面是东，学校在图书馆的东面。选 C。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"一面彩旗随风飘扬，如果吹南风，彩旗就往（　）方向飘。","options":["A.南", "B.北", "C.西"]}', 'B', '南风从南边吹来，彩旗顺着风向往北飘。选 B。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 2, '{"stem":"傍晚，玲玲和爸爸、妈妈在百合公园赏花，她转头看到左侧有一轮红红的夕阳，玲玲正在往（　）方向走。","options":["A.东", "B.南", "C.北"]}', 'C', '傍晚太阳在西边，左侧是夕阳说明左边是西：面向北时左边才是西，所以玲玲正往北走。选 C。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '单选', 3, '{"stem":"下面说法错误的是（　）。","options":["A.北的对面是南", "B.在陌生的地方，知道东、西、南、北中的一个方向就能判断出其他三个方向", "C.面向早晨的太阳，你的右面是北"]}', 'C', '面向早晨的太阳（东方）时，右面是南不是北，③说法错误；①南北相对正确；②知道一个方向即可推出其余三个方向，正确。选 C。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem":"在地图上的方向，上面是北方，右边是南方。（　）","options":null}', '×', '地图上北下南、左西右东：上面是北、右边是东。说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem":"周一升国旗时，琳琳面朝北向国旗敬礼，她的右面是东面。（　）","options":null}', '√', '面向北时，左面是西、右面是东。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem":"我国四大发明之一的指南针，可以帮助人们辨认方向。（　）","options":null}', '√', '指南针总是一端指南、一端指北，能帮助辨认方向。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 1, '{"stem":"教学楼在操场的西面，操场就在教学楼的东面。（　）","options":null}', '√', '两个位置互换后方向相反：西的对面是东。说法正确。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, deleted, reviewed, images) VALUES (38, '数学', '二年级', '判断', 2, '{"stem":"小赵坐在东面，小钱坐在西面，小孙坐在南面，小孙和小赵是相对的。（　）","options":null}', '×', '相对的是相反方向：小赵（东）与小钱（西）相对，小孙（南）应与北面的人相对。小孙和小赵不相对。说法错误。', 'paper', '[]', 0, 1, '["paper_png/yg2_sx/p031.png"]');
